const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Request body size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check endpoint with basic validation
app.get('/health', [
  // Validate optional parameters
  (req, res, next) => {
    const { format } = req.query;
    if (format && !['json', 'simple'].includes(format)) {
      return res.status(400).json({
        error: 'Invalid format parameter. Use \"json\" or \"simple\".'
      });
    }
    next();
  }
], (req, res) => {
  const format = req.query.format || 'json';

  if (format === 'simple') {
    res.json({ status: 'ok' });
  } else {
    res.json({ 
      status: 'ok', 
      // Reduced precision to avoid timestamp correlation attacks
      timestamp: new Date().toISOString().split('.')[0] + 'Z'
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', [
  // Validate and sanitize query parameters
  (req, res, next) => {
    const { id, name, limit } = req.query;

    // Validate ID if provided
    if (id && (!/^[0-9]+$/.test(id) || parseInt(id) <= 0)) {
      return res.status(400).json({
        error: 'Invalid user ID. Must be a positive integer.'
      });
    }

    // Validate and sanitize name
    if (name && (typeof name !== 'string' || name.trim().length === 0 || name.length > 100)) {
      return res.status(400).json({
        error: 'Invalid name parameter.'
      });
    }

    // Validate limit
    if (limit && (!/^[0-9]+$/.test(limit) || parseInt(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a number between 1 and 100.'
      });
    }

    next();
  }
], (req, res) => {
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const { id, name, limit } = req.query;

  // Filter by ID
  if (id) {
    users = users.filter(user => user.id === parseInt(id));
  }

  // Filter by name (case insensitive)
  if (name) {
    const searchTerm = name.trim().toLowerCase();
    users = users.filter(user => 
      user.name.toLowerCase().includes(searchTerm)
    );
  }

  // Apply limit
  if (limit) {
    users = users.slice(0, parseInt(limit));
  }

  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Uncaught error:', err);
  res.status(500).json({
    error: 'Internal server error'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

