const express = require('express');
const helmet = require('helmet'); // Requires: npm install helmet
const rateLimit = require('express-rate-limit'); // Requires: npm install express-rate-limit

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later',
  headers: true,
});

// Apply rate limiter to all requests
app.use(limiter);

// Middleware for logging requests
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
  next();
});

// Parse JSON bodies
app.use(express.json());

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Reject requests with excessive query parameters
  const queryParamCount = Object.keys(req.query).length;
  if (queryParamCount > 10) {
    return res.status(400).json({
      error: 'Too many query parameters',
      message: 'Request contains an excessive number of query parameters'
    });
  }

  // Validate parameter names don't contain suspicious characters
  for (const key of Object.keys(req.query)) {
    if (!/^[a-zA-Z0-9_]+$/.test(key)) {
      return res.status(400).json({
        error: 'Invalid parameter name',
        message: 'Query parameter names can only contain letters, numbers, and underscores'
      });
  }
  }
  next();
};

// Apply validation to all routes
app.use(validateQueryParams);

