require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');

// Configure logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    //
    // - Write to all logs with level `info` and below to `combined.log` 
    // - Write all logs error (and below) to `error.log`.
    //
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// If we're not in production then log to the console
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*' // Configure allowed origins in production
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests
app.use(limiter);

// Body parsing with limits
app.use(express.json({
  limit: '10kb' // Limit request body size
}));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });
  next();
});

// Health check endpoint with input validation
app.get('/health', [
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean')
], (req, res) => {
  // Validate request
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    };

    // Add detailed info if requested
    if (req.query.detailed === 'true') {
      healthData.process = {
        memory: process.memoryUsage(),
        uptime: process.uptime()
      };
    }

    res.json(healthData);
  } catch (error) {
    logger.error('Health check error:', { error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation and pagination
app.get('/users', [
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('search').optional().trim().escape().isLength({ max: 50 }).withMessage('Search term too long')
], (req, res) => {
  // Validate request
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    // Simulated user data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Extract query parameters with defaults
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const search = req.query.search?.toLowerCase() || '';

    // Filter users if search query provided
    let filteredUsers = allUsers;
    if (search) {
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(search) || 
        user.email.toLowerCase().includes(search)
      );
    }

    // Calculate pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Prepare response
    const response = {
      users: paginatedUsers,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(filteredUsers.length / limit),
        totalUsers: filteredUsers.length,
        hasNext: endIndex < filteredUsers.length,
        hasPrev: startIndex > 0
      }
    };

    res.json(response);
  } catch (error) {
    logger.error('Users endpoint error:', { error: error.message });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handling middleware
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', { error: error.message, stack: error.stack });

  // Set default error status
  const status = error.status || 500;

  // In production, don't send stack trace
  const response = {
    error: {
      message: status === 500 ? 'Internal server error' : error.message
    }
  };

  if (process.env.NODE_ENV !== 'production') {
    response.error.stack = error.stack;
  }

  res.status(status).json(response);
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  logger.warn('404 route not found:', { method: req.method, url: req.url });
  res.status(404).json({ error: 'Route not found' });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

module.exports = { app, server, logger };

