const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(mongoSanitize()); // NoSQL injection protection
app.use(xss()); // XSS protection

// Body parser with limits
app.use(express.json({
  limit: '10kb' // Limit payload size
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api', limiter); // Apply to API routes

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Input validation - check for potential malicious parameters
    const { limit, offset } = req.query;

    // Validate query parameters if present
    if (limit !== undefined) {
      const limitNum = parseInt(limit);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid limit parameter. Must be a number between 1 and 100.'
        });
      }
    }

    if (offset !== undefined) {
      const offsetNum = parseInt(offset);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid offset parameter. Must be a non-negative number.'
        });
      }
