require('express-async-errors'); // Handle async errors automatically

const express = require('express');
const rateLimit = require('rate-limiter-flexible');
const helmet = require('helmet');
const cors = require('cors');
const { body, query, param, validationResult } = require('express-validator');
const app = express();

// Load environment variables
require('dotenv').config();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // Can be enabled with proper configuration
}));

// Rate limiting - 100 requests per 15 minutes per IP
const limiter = new rateLimit.RateLimiterMemory({
  points: 100,
  duration: 900, // 15 minutes
});

app.use((req, res, next) => {
  limiter.consume(req.ip)
    .then(() => {
      next();
    })
    .catch(() => {
      res.status(429).json({ error: 'Rate limit exceeded' });
    });
});

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true,
}));

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));

// Security logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Input validation and sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }
  next();
};

// Health endpoint with input validation
app.get('/health', [
  query('detailed').optional().isBoolean().toBoolean(),
  sanitizeInput
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Invalid parameters', details: errors.array() });
  }

  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  };

  // Add detailed info if requested
  if (req.query.detailed) {
    healthData.environment = process.env.NODE_ENV || 'development';
  }

  res.json(healthData);
});

// Users endpoint with proper validation and pagination
app.get('/users', [
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  query('search').optional().isString().trim().escape(),
  sanitizeInput
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Invalid parameters', details: errors.array() });
  }

  // Default values
  const limit = req.query.limit || 10;
  const offset = req.query.offset || 0;
  const search = req.query.search || '';

  // Mock users data
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter by search if provided
  if (search) {
    const searchTerm = search.toLowerCase();
    users = users.filter(user => 
      user.name.toLowerCase().includes(searchTerm) || 
      user.email.toLowerCase().includes(searchTerm)
    );
  }

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    total: users.length,
    limit,
    offset,
    hasMore: offset + limit < users.length
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Distinguish between operational and programmer errors
  if (error.isOperational) {
    res.status(error.statusCode || 500).json({
      error: error.message || 'An error occurred'
    });
  } else {
    // Hide internal details in production
    res.status(500).json({
      error: process.env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : error.message || 'An error occurred'
    });
  }
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

