"use strict";

// Improved version with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const { body, validationResult, param } = require('express-validator');

const app = express();

// Security middleware
// Protect against well-known web vulnerabilities
app.use(helmet());

// Parse JSON with size limit to prevent DOS
app.use(express.json({ limit: '10kb' }));

// Sanitize user input to prevent XSS
app.use(xss());

// Configure CORS - restrict to specific origins in production
const corsOptions = {
  origin: process.env.CORS_ORIGIN || '*', // In production, replace '*' with actual domains
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes',
    code: 'RATE_LIMIT_EXCEEDED'
  },
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const userAgent = req.get('User-Agent') || 'unknown';
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} - ${userAgent}`);

  // Store start time for response time calculation
  const start = Date.now();

  // Log when response ends
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} ${res.statusCode} - ${duration}ms`);
  });

  next();
});

// Health check with proper error handling
app.get('/health', [
  // Validate query parameters if any
  (req, res, next) => {
    // Middleware to validate query params
    const schema = {
      details: { isBoolean: true, optional: true }
    };

    // In a real app, you'd use express-validator for this
    if (req.query.details !== undefined) {
      if (req.query.details !== 'true' && req.query.details !== 'false') {
        return res.status(400).json({
          error: 'Invalid details parameter. Must be "true" or "false"',
          code: 'INVALID_PARAMETER'
        });
      }
    }
    next();
  }
], (req, res) => {
  try {
    const includeDetails = req.query.details === 'true';

    if (includeDetails) {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development',
        version: '1.0.0'
      });
    } else {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      });
    }
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Mock users data
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Users endpoint with input validation and error handling
app.get('/users', [
  // Validate query parameters
  (req, res, next) => {
    // Validate page parameter
    if (req.query.page !== undefined) {
      const page = parseInt(req.query.page);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({
          error: 'Page must be a positive integer',
          code: 'INVALID_PAGE'
        });
      }
    }

    // Validate limit parameter
    if (req.query.limit !== undefined) {
      const limit = parseInt(req.query.limit);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Limit must be a positive integer between 1 and 100',
          code: 'INVALID_LIMIT'
        });
      }
    }

    next();
  }
], (req, res) => {
  try {
    // Extract pagination parameters
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    // Get paginated results
    const results = {};

    if (endIndex < users.length) {
      results.next = {
        page: page + 1,
        limit: limit
      };
    }

    if (startIndex > 0) {
      results.previous = {
        page: page - 1,
        limit: limit
      };
    }

    results.data = users.slice(startIndex, endIndex);
    results.pagination = {
      page,
      limit,
      total: users.length,
      pages: Math.ceil(users.length / limit)
    };

    res.json(results);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Get user by ID with validation
app.get('/users/:id', [
  // Validate ID parameter
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      code: 'VALIDATION_ERROR',
      details: errors.array()
    });
  }

  try {
    const id = parseInt(req.params.id);
    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        code: 'NOT_FOUND'
      });
    }

    res.json(user);
  } catch (error) {
    console.error(`Error fetching user ${req.params.id}:`, error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Set locals, only providing error in development
  res.locals.message = error.message;
  res.locals.error = req.app.get('env') === 'development' ? error : {};

  // Send error response
  res.status(error.status || 500).json({
    error: 'Internal server error',
    code: 'INTERNAL_ERROR'
  });
});

// Handle 404 - Route not found
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`,
    code: 'NOT_FOUND'
  });
});

const PORT = process.env.PORT || 3000;

// Start server with error handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.syscall !== 'listen') {
    throw error;
  }

  const bind = typeof PORT === 'string' ? 'Pipe ' + PORT : 'Port ' + PORT;

  // Handle specific listen errors with friendly messages
  switch (error.code) {
    case 'EACCES':
      console.error(bind + ' requires elevated privileges');
      process.exit(1);
      break;
    case 'EADDRINUSE':
      console.error(bind + ' is already in use');
      process.exit(1);
      break;
    default:
      throw error;
  }
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

