const express = require('express');
const app = express();

// Simple rate limiting object to track IP requests
const requestRateLimit = {};
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

// Security headers middleware (lightweight alternative to helmet)
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'; frame-ancestors 'none'; form-action 'self'");

  // Rate limiting
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestRateLimit[ip]) {
    requestRateLimit[ip] = [];
  }

  // Clean old requests outside the window
  requestRateLimit[ip] = requestRateLimit[ip].filter(timestamp => {
    return now - timestamp < WINDOW_MS;
  });

  if (requestRateLimit[ip].length >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.'
    });
  }

  // Add current request timestamp
  requestRateLimit[ip].push(now);

  next();
});

