const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "*.example.com"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'", "data:", "*.example.com"],
      objectSrc: ["'none'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  frameguard: {
    action: 'deny'
  }
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limit to all requests except health check
app.use('/health', limiter);
app.use('/', (req, res, next) => {
  if (req.path !== '/health') {
    limiter(req, res, next);
  } else {
    next();
  }
});

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Body parsing with size limits
app.use(express.json({
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-DNS-Prefetch-Control', 'off');
  res.setHeader('X-Download-Options', 'noopen');
  res.setHeader('X-Permitted-Cross-Domain-Policies', 'none');
  res.setHeader('Referrer-Policy', 'no-referrer');

  // Add request ID for tracing
  const requestId = require('crypto').randomBytes(16).toString('hex');
  res.setHeader('X-Request-Id', requestId);
  req.id = requestId;

  next();
});

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Validate common parameters
  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be between 1 and 100.',
        requestId: req.id
      });
    }
  }

  if (req.query.page) {
    const page = parseInt(req.query.page);
    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.',
        requestId: req.id
      });
    }
  }

  next();
};

// Apply validation to all routes
app.use(validateQueryParams);

// Health check route
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      requestId: req.id
    });
  } catch (error) {
    console.error(`Health check error [${req.id}]:`, error);
    res.status(500).json({
      error: 'Health check failed',
      requestId: req.id
    });
  }
});

// Users route with improved error handling
app.get('/users', (req, res) => {
  try {
    // Simulated users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Handle pagination if requested
    const limit = req.query.limit ? parseInt(req.query.limit) : users.length;
    const page = req.query.page ? parseInt(req.query.page) : 1;
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        pages: Math.ceil(users.length / limit),
        page,
        limit
      },
      requestId: req.id
    });

  } catch (error) {
    console.error(`Users route error [${req.id}]:`, error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      requestId: req.id
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.path} not found`,
    requestId: req.id
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error(`Unhandled error [${req.id}]:`, error);

  // Determine status code
  const statusCode = error.statusCode || error.status || 500;

  // Prepare error response
  const errorResponse = {
    error: error.message || 'Internal server error',
    requestId: req.id
  };

  // Add error details in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = error.stack;
    errorResponse.details = error;
  }

  res.status(statusCode).json(errorResponse);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Graceful shutdown
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

